//! # Rocket - Code Generation for NAPI & TypeScript
//!
//! This module implements code generation and route meta utilities for Rocket NAPI bindings.
//! It supports registering generated route definitions, generating OpenAPI / JSON schema / route metadata,
//! and building Rocket route / catcher structures for TypeScript (Node.js) code generation.

use std::collections::HashMap;
use napi_derive::napi;

/// Route metadata generated by code generation or decorator utilities.
#[napi(object)]
#[derive(Clone, Debug)]
pub struct RouteCodegenMeta {
    pub method: String,
    pub path: String,
    pub name: Option<String>,
    pub rank: Option<i32>,
    pub format: Option<String>,
    pub data_param: Option<String>,
    pub query_params: Vec<String>,
    pub path_params: Vec<String>,
}

/// Generated code artifact for TypeScript routes.
#[napi(object)]
#[derive(Clone, Debug)]
pub struct CodegenOutput {
    pub ts_code: String,
    pub routes: Vec<RouteCodegenMeta>,
}

/// Codegen helper class exposed via NAPI.
#[napi]
pub struct Codegen {
    routes: Vec<RouteCodegenMeta>,
}

#[napi]
impl Codegen {
    #[napi(constructor)]
    pub fn new() -> Self {
        Self { routes: Vec::new() }
    }

    /// Add route metadata to the codegen generator.
    #[napi]
    pub fn add_route(&mut self, meta: RouteCodegenMeta) {
        self.routes.push(meta);
    }

    /// Generate TypeScript route definition code for the registered routes.
    #[napi]
    pub fn generate_ts(&self) -> CodegenOutput {
        let mut code = String::from("// Auto-generated by Rocket Codegen\n\n");
        code.push_str("export const routes = {\n");

        for route in &self.routes {
            let name = route.name.as_deref().unwrap_or("handler");
            let method = route.method.to_uppercase();
            code.push_str(&format!(
                "  \"{}\": {{\n    {}: async (req: any) => {{ /* {} */ }},\n  }},\n",
                route.path, method, name
            ));
        }

        code.push_str("};\n");

        CodegenOutput {
            ts_code: code,
            routes: self.routes.clone(),
        }
    }
}

fn extract_param_name(raw: &str) -> Option<String> {
    let s = raw.trim();
    if let Some(inner) = s.strip_prefix('<') {
        if let Some(name) = inner.strip_suffix('>') {
            return Some(name.trim_end_matches("..").to_string());
        }
    } else if let Some(name) = s.strip_prefix(':') {
        return Some(name.to_string());
    } else if !s.is_empty() {
        return Some(s.to_string());
    }
    None
}

/// Helper function to parse a Rocket-style route pattern into parameters metadata.
#[napi]
pub fn parse_route_pattern(pattern: String) -> HashMap<String, Vec<String>> {
    let mut path_params = Vec::new();
    let mut query_params = Vec::new();

    let parts: Vec<&str> = pattern.split('?').collect();
    let path_part = parts[0];

    for seg in path_part.split('/') {
        if let Some(inner) = seg.strip_prefix('<') {
            if let Some(name) = inner.strip_suffix('>') {
                let clean_name = name.trim_end_matches("..");
                path_params.push(clean_name.to_string());
            }
        } else if let Some(name) = seg.strip_prefix(':') {
            path_params.push(name.to_string());
        }
    }

    if parts.len() > 1 {
        for q in parts[1].split('&') {
            if q.is_empty() {
                continue;
            }
            if let Some((key, val)) = q.split_once('=') {
                if let Some(param) = extract_param_name(val).or_else(|| extract_param_name(key)) {
                    query_params.push(param);
                }
            } else if let Some(param) = extract_param_name(q) {
                query_params.push(param);
            }
        }
    }

    let mut result = HashMap::new();
    result.insert("path_params".to_string(), path_params);
    result.insert("query_params".to_string(), query_params);
    result
}
